  background-color: rgb(0,150,255);
  align-items: stretch;
}

.flex-container &gt; div {
  background-color: #f1f1f1;
  width: 200px; /*--control image size--*/
  margin: 5px;
  border: 2px solid #fff;
  border-radius: 7px;
}

img {
  width: 100%; 
  height:auto; 
  border-radius: 5px; 
  cursor: pointer; 
  display: block; 
  margin-left: auto; 
  margin-right: auto;
}
