Q: How can I connect to AWS IoT Core MQTT over WebSocket from browser A: <p>Thanks guys for your answers. I found what I had missed out and that's the attaching of IoT core policy to identity id of the logged in user.</p>
<ol>
<li>I replaced the SigV4 URL + websocket with the AWS Amplify PubSub.</li>
<li>Created a Lambda with inbuilt IAM authorizer at gateway to attach the logged in user's identity id with the IoT Core policy.</li>
</ol>
<p>Now everything works as expected. I hope my answer would help others also who want to achieve the same.</p>
<h3>Updated service code:</h3>
<pre class="lang-js prettyprint-override"><code>import * as api from &quot;@aws-amplify/api-rest&quot;;
import { PubSub } from &quot;@aws-amplify/pubsub&quot;;
import { AWS_CONFIG, LambdaGatewayID } from &quot;../aws-config&quot;;
class IotService {
  public async connect() {
    const res = await api.post({
      path: &quot;/auth/iot&quot;,
      apiName: LambdaGatewayID.V1,
    }).response;
    if (res.statusCode === 200) {
      const data = (await res.body.json()) as { policyAttached: boolean };
      if (data.policyAttached) {
        const device = new PubSub({
          endpoint: `wss://${AWS_CONFIG.iot.endpoint}/mqtt`,
          region: AWS_CONFIG.iot.region,
        });
        device
          .subscribe({
            topics: [&quot;topic/name&quot;],
          })
          .subscribe({
            next(value) {
              console.log(&quot;PubSub Message&quot;, value);
            },
          });
      }
    }
  }
}

export const iotService = new IotService();

</code></pre>
<h3>Lambda Function</h3>
<pre class="lang-js prettyprint-override"><code>import { IoTClient, AttachPolicyCommand } from &quot;@aws-sdk/client-iot&quot;;
const iot = new IoTClient({
  region: process.env.AWS_REGION,
});

const IDENTITY_POOL_ID = process.env.IDENTITY_POOL_ID;
const IOT_POLICY_NAME = process.env.IOT_POLICY_NAME;
const COGNITO_USER_POOL_ID = process.env.COGNITO_USER_POOL_ID;
const textAuthenticated = &quot;authenticated&quot;;

const createResponse = (body = &quot;&quot;, statusCode = 200) =&gt; {
  return {
    statusCode,
    body: JSON.stringify(body),
    headers: {
      &quot;Content-Type&quot;: &quot;application/json&quot;,
    },
  };
};

export const handler = async (event) =&gt; {
  const claims = event.requestContext?.authorizer?.iam?.cognitoIdentity || {};
  const IdentityId = claims.identityId;
  if (
    IdentityId &amp;&amp;
    claims.identityPoolId === IDENTITY_POOL_ID &amp;&amp;
    claims.amr?.includes?.(textAuthenticated) &amp;&amp;
    claims.amr?.some?.((i) =&gt; i.includes(COGNITO_USER_POOL_ID))
  ) {
    try {
      const attachCmd = new AttachPolicyCommand({
        policyName: IOT_POLICY_NAME,
        target: IdentityId,
      });
      await iot.send(attachCmd);
      return createResponse({
        identityId: IdentityId,
        policyAttached: true,
      });
    } catch (err) {
      if (err.name !== &quot;ResourceAlreadyExistsException&quot;) {
        return createResponse({
          identityId: IdentityId,
          policyAttached: true,
        });
      }
      console.error(err);
      return createResponse({
        identityId: IdentityId,
        policyAttached: false,
      });
    }
  }
  return createResponse({ message: &quot;Access forbidden&quot; }, 403);
};

</code></pre>
